//
// Gerado a partir de "Orçamento_2027.xlsm":
//   • aba ORÇAMENTO 2027 → grupos, contas e a ordem da DRE;
//   • aba SUPORTE        → subitens 6.1.1.01.* da conta
//     4.1.4.01.01.018 (CUSTO MOD PROJETOS C/TAD), com as subdivisões
//     (Despesas com pessoal, Custos gerais, Veículos, Viagens).
//
// As linhas já gravadas no Dataverse guardam código, conta e grupo
// como TEXTO: mudar este arquivo nunca altera o histórico. Nomes de
// grupos da versão anterior do plano são convertidos por
// ALIAS_GRUPOS ao ler.
//
// Linhas calculadas (Receita Operacional Líquida, Lucro Bruto, LAIR,
// Lucro Líquido, EBITDA…) e as seções (Deduções, Custos de operação,
// Despesas operacionais) estão em dreOrcamento.ts.
// ============================================================

export interface IContaOrcamento {
  grupo: string;
  codigo: string;
  conta: string;
  // Subitem de outra conta (ex.: 6.1.1.01.* → 4.1.4.01.01.018). A conta
  // "mãe" não recebe digitação: o valor dela é a soma dos subitens.
  pai?: string;
  // Subdivisão dentro da conta mãe (ex.: "6.1.1.01.02 · CUSTOS GERAIS").
  subdivisao?: string;
}

